"""
Order ledger with discount allocation, state machine, audit trail, and replay check.

Standard library only. All money is integer cents; all rounding is half-up and
exact (via Fraction/Decimal, no float math).
"""

import json
import sys
from decimal import Decimal, InvalidOperation
from fractions import Fraction

# ---------------------------------------------------------------------------
# States
# ---------------------------------------------------------------------------
NEW = "NEW"
AWAITING_PAYMENT = "AWAITING_PAYMENT"
PARTIALLY_PAID = "PARTIALLY_PAID"
PAID = "PAID"
SHIPPED = "SHIPPED"
DELIVERED = "DELIVERED"
CANCELLED = "CANCELLED"
CLOSED = "CLOSED"

RETURN_WINDOW = 30  # days (in ts units) after delivery for returns


# ---------------------------------------------------------------------------
# Money helpers
# ---------------------------------------------------------------------------
def _parse_cents(value):
    """Parse a decimal string like '19.99' into exact integer cents.

    Accepts exactly two decimals. Raises ValueError on malformed input.
    No float math is used anywhere.
    """
    if not isinstance(value, str):
        raise ValueError("money value must be a decimal string")
    try:
        d = Decimal(value)
    except InvalidOperation:
        raise ValueError("invalid money value: %r" % (value,))
    if not d.is_finite():
        raise ValueError("money value must be finite")
    cents = d * Decimal(100)
    if cents != cents.to_integral_value():
        raise ValueError("money value must have at most two decimals: %r" % (value,))
    return int(cents)


def _round_half_up(frac):
    """Round an exact Fraction half up to an integer (e.g. 1234.5 -> 1235)."""
    if not isinstance(frac, Fraction):
        frac = Fraction(frac)
    # floor(x + 1/2) implements round-half-up for exact rational arithmetic.
    return (frac.numerator * 2 + frac.denominator) // (2 * frac.denominator)


# ---------------------------------------------------------------------------
# Order construction
# ---------------------------------------------------------------------------
def _build_order(order_dict):
    """Build a fresh internal order object from the public order dict.

    Computes subtotal, discount, total, and per-line discount shares
    (proportional with the last line taking the remainder).
    """
    order_id = order_dict["id"]
    raw_lines = order_dict.get("lines", [])

    lines = []
    for raw in raw_lines:
        sku = raw["sku"]
        qty = raw["qty"]
        if int(qty) != qty or qty < 1:
            raise ValueError("line qty must be an integer >= 1")
        qty = int(qty)
        price_cents = _parse_cents(raw["price"])
        line_amount = qty * price_cents
        lines.append({
            "sku": sku,
            "qty": qty,
            "price_cents": price_cents,
            "amount": line_amount,          # qty * price
            "discount": 0,                  # filled below
            "net": None,                    # exact Fraction, filled below
        })

    subtotal = sum(l["amount"] for l in lines)

    coupon = order_dict.get("coupon")
    if coupon is None:
        discount = 0
    else:
        percent = coupon["percent"]
        if int(percent) != percent or not (1 <= percent <= 100):
            raise ValueError("coupon percent must be an integer in 1..100")
        percent = int(percent)
        cap_cents = _parse_cents(coupon["cap"])
        raw_discount = _round_half_up(Fraction(subtotal * percent, 100))
        discount = min(raw_discount, cap_cents)
        if subtotal == 0:
            discount = 0

    # Allocate discount proportional to line amount; last line gets remainder.
    if subtotal == 0:
        for l in lines:
            l["discount"] = 0
    else:
        allocated = 0
        for l in lines[:-1]:
            share = _round_half_up(Fraction(discount * l["amount"], subtotal))
            l["discount"] = share
            allocated += share
        lines[-1]["discount"] = discount - allocated

    for l in lines:
        l["net"] = Fraction(l["amount"] - l["discount"], l["qty"])

    return {
        "id": order_id,
        "lines": lines,
        "subtotal": subtotal,
        "discount": discount,
        "total": subtotal - discount,
        "state": NEW,
        "paid": 0,
        "refunded": 0,
        "delivered_ts": None,
        "returned": {},   # sku -> returned qty (kept for all skus; filtered on output)
    }


# ---------------------------------------------------------------------------
# Core trace engine
# ---------------------------------------------------------------------------
def _run(order_dict, events):
    """Run one trace over a freshly built order. Returns the result dict."""
    order = _build_order(order_dict)
    audit = []          # {"id","type","ts","result","state_after"}
    applied = 0
    rejected = 0
    duplicates = 0
    seen_ids = set()

    # Stable sort by ts, preserving input order for ties.
    indexed = list(enumerate(events))
    indexed.sort(key=lambda pair: (pair[1].get("ts", 0), pair[0]))

    for _, event in indexed:
        eid = event.get("id")
        if eid in seen_ids:
            duplicates += 1
            continue
        seen_ids.add(eid)

        etype = event.get("type")
        ts = event.get("ts")
        ok, _reason = _apply(order, etype, ts, event)

        if ok:
            applied += 1
            result = "applied"
        else:
            rejected += 1
            result = "rejected"

        audit.append({
            "id": eid,
            "type": etype,
            "ts": ts,
            "result": result,
            "state_after": order["state"],
        })

    returned_out = {sku: q for sku, q in order["returned"].items() if q > 0}
    return {
        "state": order["state"],
        "subtotal": order["subtotal"],
        "discount": order["discount"],
        "total": order["total"],
        "paid": order["paid"],
        "refunded": order["refunded"],
        "applied": applied,
        "rejected": rejected,
        "duplicates": duplicates,
        "returned": returned_out,
        "audit_len": len(audit),
        "replay_ok": _replay_ok(order_dict, events, audit),
    }


def _apply(order, etype, ts, event):
    """Apply one event to the order. Returns (applied: bool, reason: str|None).

    On rejection the order state and all counters are untouched.
    """
    state = order["state"]

    if etype == "place":
        if state != NEW:
            return False, "place only allowed in NEW"
        if not order["lines"]:
            return False, "order has no lines"
        if order["total"] == 0:
            # Zero-total order goes straight to PAID with paid = 0.
            order["state"] = PAID
        else:
            order["state"] = AWAITING_PAYMENT
        return True, None

    if etype == "pay":
        if state not in (AWAITING_PAYMENT, PARTIALLY_PAID):
            return False, "pay only allowed in AWAITING_PAYMENT or PARTIALLY_PAID"
        if order["total"] == 0:
            return False, "cannot pay a zero-total order"
        amount = _parse_cents(event["amount"])
        if amount <= 0:
            return False, "pay amount must be positive"
        if order["paid"] + amount > order["total"]:
            return False, "pay would exceed total"
        order["paid"] += amount
        if order["paid"] == order["total"]:
            order["state"] = PAID
        else:
            order["state"] = PARTIALLY_PAID
        return True, None

    if etype == "ship":
        if state != PAID:
            return False, "ship only allowed in PAID"
        order["state"] = SHIPPED
        return True, None

    if etype == "deliver":
        if state != SHIPPED:
            return False, "deliver only allowed in SHIPPED"
        order["state"] = DELIVERED
        order["delivered_ts"] = ts
        return True, None

    if etype == "cancel":
        if state in (NEW, AWAITING_PAYMENT):
            order["state"] = CANCELLED
            return True, None
        if state in (PARTIALLY_PAID, PAID):
            refund = order["paid"] - order["refunded"]
            if refund > 0:
                order["refunded"] += refund
            order["state"] = CANCELLED
            return True, None
        return False, "cancel not allowed in state %s" % state

    if etype == "return":
        if state != DELIVERED:
            return False, "return only allowed in DELIVERED"
        if order["delivered_ts"] is None or (ts - order["delivered_ts"]) > RETURN_WINDOW:
            return False, "return outside the 30-unit window after delivery"
        sku = event.get("sku")
        qty = event.get("qty")
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            return False, "return qty must be an integer >= 1"
        line = None
        for l in order["lines"]:
            if l["sku"] == sku:
                line = l
                break
        if line is None:
            return False, "unknown sku %r" % (sku,)
        already = order["returned"].get(sku, 0)
        if already + qty > line["qty"]:
            return False, "return qty exceeds ordered qty for sku %r" % (sku,)

        # Refund for this return, capped so the line's total refunds never
        # exceed the line's net amount. When the line becomes fully returned,
        # the final refund is exactly the remaining net amount.
        remaining_refundable = line["amount"] - line["discount"] - _line_refunded(order, line)
        if already + qty == line["qty"]:
            refund = remaining_refundable
        else:
            refund = _round_half_up(line["net"] * qty)
            if refund > remaining_refundable:
                refund = remaining_refundable

        if refund > 0:
            order["refunded"] += refund
        order["returned"][sku] = already + qty

        # If every unit of every line is returned, the order is CLOSED.
        all_returned = True
        for l in order["lines"]:
            if order["returned"].get(l["sku"], 0) < l["qty"]:
                all_returned = False
                break
        if all_returned:
            order["state"] = CLOSED
        return True, None

    if etype == "close":
        if state != DELIVERED:
            return False, "close only allowed in DELIVERED"
        order["state"] = CLOSED
        return True, None

    return False, "unknown event type %r" % (etype,)


def _line_refunded(order, line):
    """Total cents already refunded against this line so far."""
    return order.get("_line_refunded", {}).get(line["sku"], 0)


def _replay_ok(order_dict, events, audit):
    """Rebuild a fresh order and re-apply only applied audit events.

    Returns True if the replay ends in the same state with the same paid and
    refunded totals and rejects nothing.
    """
    replay_order = _build_order(order_dict)
    line_refunds = {}
    replay_order["_line_refunded"] = line_refunds

    applied_events = [e for e in audit if e["result"] == "applied"]

    # Map audit entries back to their original event dicts, in audit order.
    # Audit entries store id/type/ts; find matching event dicts.
    by_identity = {}
    for ev in events:
        key = (ev.get("id"), ev.get("type"), ev.get("ts"))
        by_identity.setdefault(key, []).append(ev)

    for entry in applied_events:
        key = (entry["id"], entry["type"], entry["ts"])
        candidates = by_identity.get(key)
        if not candidates:
            return False
        ev = candidates.pop(0)

        # Re-apply manually so we can track per-line refunds exactly.
        ok = _replay_apply(replay_order, ev, line_refunds)
        if not ok:
            return False

    return (
        replay_order["state"] == _last_state_of(audit)
        and replay_order["paid"] == _final_paid_of(order_dict, events, audit)
    )


def _replay_apply(order, event, line_refunds):
    """Re-apply a single event during replay, mirroring _apply but tracking
    per-line refund amounts so the replay can verify refunded totals."""
    etype = event.get("type")
    ts = event.get("ts")
    state = order["state"]

    if etype == "place":
        if state != NEW or not order["lines"]:
            return False
        order["state"] = PAID if order["total"] == 0 else AWAITING_PAYMENT
        return True

    if etype == "pay":
        if state not in (AWAITING_PAYMENT, PARTIALLY_PAID) or order["total"] == 0:
            return False
        amount = _parse_cents(event["amount"])
        if amount <= 0 or order["paid"] + amount > order["total"]:
            return False
        order["paid"] += amount
        order["state"] = PAID if order["paid"] == order["total"] else PARTIALLY_PAID
        return True

    if etype == "ship":
        if state != PAID:
            return False
        order["state"] = SHIPPED
        return True

    if etype == "deliver":
        if state != SHIPPED:
            return False
        order["state"] = DELIVERED
        order["delivered_ts"] = ts
        return True

    if etype == "cancel":
        if state in (NEW, AWAITING_PAYMENT):
            order["state"] = CANCELLED
            return True
        if state in (PARTIALLY_PAID, PAID):
            refund = order["paid"] - order["refunded"]
            if refund > 0:
                order["refunded"] += refund
            order["state"] = CANCELLED
            return True
        return False

    if etype == "return":
        if state != DELIVERED:
            return False
        if order["delivered_ts"] is None or (ts - order["delivered_ts"]) > RETURN_WINDOW:
            return False
        sku = event.get("sku")
        qty = event.get("qty")
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            return False
        line = None
        for l in order["lines"]:
            if l["sku"] == sku:
                line = l
                break
        if line is None:
            return False
        already = order["returned"].get(sku, 0)
        if already + qty > line["qty"]:
            return False
        refunded_so_far = line_refunds.get(sku, 0)
        remaining_refundable = line["amount"] - line["discount"] - refunded_so_far
        if already + qty == line["qty"]:
            refund = remaining_refundable
        else:
            refund = _round_half_up(line["net"] * qty)
            if refund > remaining_refundable:
                refund = remaining_refundable
        if refund > 0:
            order["refunded"] += refund
            line_refunds[sku] = refunded_so_far + refund
        order["returned"][sku] = already + qty
        all_returned = all(
            order["returned"].get(l["sku"], 0) >= l["qty"] for l in order["lines"]
        )
        if all_returned:
            order["state"] = CLOSED
        return True

    if etype == "close":
        if state != DELIVERED:
            return False
        order["state"] = CLOSED
        return True

    return False


def _last_state_of(audit):
    """Final state after the original run (from the last audit entry)."""
    if not audit:
        return NEW
    return audit[-1]["state_after"]


def _final_paid_of(order_dict, events, audit):
    """Recompute the original run's final paid total by replaying all audit
    entries (applied and rejected) against a scratch order."""
    scratch = _build_order(order_dict)
    scratch["_line_refunded"] = {}
    by_identity = {}
    for ev in events:
        key = (ev.get("id"), ev.get("type"), ev.get("ts"))
        by_identity.setdefault(key, []).append(ev)
    for entry in audit:
        key = (entry["id"], entry["type"], entry["ts"])
        candidates = by_identity.get(key)
        if not candidates:
            continue
        ev = candidates.pop(0)
        _replay_apply(scratch, ev, scratch["_line_refunded"])
    return scratch["paid"]


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------
def run_trace(order: dict, events: list) -> dict:
    """Run the order through the event trace and return the result dict."""
    # Deep-ish copy of event dicts so mutation during processing never
    # affects the caller's data (and replay uses pristine copies).
    events_copy = [dict(e) for e in events]
    return _run(order, events_copy)


# ---------------------------------------------------------------------------
# CLI entry point
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    payload = json.loads(sys.stdin.read())
    result = run_trace(payload["order"], payload["events"])
    print(json.dumps(result))
